// features/pieces_jointes_pack/types/index.ts
import { z } from 'zod';

export const pieces_jointes_pack_Schema = z.object({
  id: z.string().uuid(),
  createdAt: z.string().datetime(),
  status: z.enum(['active', 'pending', 'archived']),
  metadata: z.record(z.unknown()).optional(),
});

